const path=require('path');
const {chromium}=require(require.resolve('playwright',{paths:['D:/projects/ptah-extension/node_modules']}));
(async()=>{const b=await chromium.launch({headless:true});const page=await b.newPage();await page.goto('file:///'+path.join(__dirname,'command-center.html').replace(/\\/g,'/'));for(const theme of ['dark','light']){const result=await page.evaluate(theme=>{document.documentElement.dataset.theme=theme;function rgb(value){let c=document.createElement('canvas');c.width=c.height=1;let x=c.getContext('2d');x.fillStyle=value;x.fillRect(0,0,1,1);return Array.from(x.getImageData(0,0,1,1).data).slice(0,3)}function lum(c){const a=c.map(v=>{v/=255;return v<=.04045?v/12.92:((v+.055)/1.055)**2.4});return a[0]*.2126+a[1]*.7152+a[2]*.0722}let style=getComputedStyle(document.documentElement),keys=['--text','--muted','--gold','--run','--need','--err','--done','--stop','--panel','--stage','--bg'];let colors=Object.fromEntries(keys.map(k=>[k,rgb(style.getPropertyValue(k).trim())]));const contrast=(a,b)=>{let x=lum(colors[a]),y=lum(colors[b]);return ((Math.max(x,y)+.05)/(Math.min(x,y)+.05)).toFixed(2)};return{theme,colors,pairs:Object.fromEntries([['--text','--panel'],['--text','--stage'],['--muted','--stage'],['--gold','--panel'],['--run','--stage'],['--need','--stage'],['--err','--stage'],['--done','--stage'],['--stop','--stage']].map(([a,b])=>[a+' on '+b,contrast(a,b)]))}},theme);console.log(JSON.stringify(result))}await b.close()})().catch(e=>{console.error(e);process.exitCode=1});
